def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b           # gcd(a, b) = gcd(b, a mod b)
    return a

def egcd(a: int, b: int):
    """Return (g, s, t) with g = gcd(a, b) = s*a + t*b (extended Euclidean algorithm)."""
    if b == 0:
        return a, 1, 0
    g, s, t = egcd(b, a % b)
    return g, t, s - (a // b) * t

def inverse(a: int, m: int) -> int:
    g, s, _ = egcd(a, m)
    if g != 1:
        raise ValueError(f"{a} has no inverse modulo {m} (gcd is {g})")
    return s % m

print("gcd(84, 30) =", gcd(84, 30))
print("egcd(84, 30) =", egcd(84, 30), " -> 6 = s*84 + t*30")
print("inverse of 17 mod 3120 =", inverse(17, 3120), "| check:", 17 * inverse(17, 3120) % 3120)
print("matches Python's pow(17, -1, 3120):", inverse(17, 3120) == pow(17, -1, 3120))
try:
    inverse(6, 9)
except ValueError as err:
    print("error:", err)
